-- script completo do banco postgresql pra vendinha de molhos de pimenta do avo bob

-- tabela de clientes que compram fiado
CREATE TABLE IF NOT EXISTS "Clientes" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "NomeCompleto" VARCHAR(150) NOT NULL,
    "Cpf" VARCHAR(14) NOT NULL,
    "DataNascimento" DATE NOT NULL,
    "Email" VARCHAR(150) NULL,

    -- nao deixa cadastrar dois clientes com o mesmo cpf
    CONSTRAINT "UQ_Clientes_Cpf" UNIQUE ("Cpf")
);

-- tabela com as tipagens de pimentas usadas nas receitas
CREATE TABLE IF NOT EXISTS "Pimentas" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nome" VARCHAR(100) NOT NULL,
    "EspecieOrigem" VARCHAR(150) NOT NULL,
    "NivelScoville" INTEGER NOT NULL,
    "CustoPorGrama" NUMERIC(10, 4) NOT NULL,

    -- garante ardencia e custo por grama positivos
    CONSTRAINT "CK_Pimentas_Scoville_Positivo" CHECK ("NivelScoville" > 0),
    CONSTRAINT "CK_Pimentas_Custo_Positivo" CHECK ("CustoPorGrama" > 0)
);

-- tabela de molhos usando heranca tph (tradicional e especial de reserva)
CREATE TABLE IF NOT EXISTS "Molhos" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nome" VARCHAR(150) NOT NULL,
    "PimentaId" INTEGER NOT NULL,
    "GramasPimentaPorFrasco" NUMERIC(10, 2) NOT NULL,
    "CustoEmbalagemIngredientes" NUMERIC(10, 2) NOT NULL,
    "PrecoVenda" NUMERIC(10, 2) NOT NULL,
    "TipoMolho" VARCHAR(30) NOT NULL,
    "TempoMaturacaoDias" INTEGER NULL,
    "CustoAdicionalBarril" NUMERIC(10, 2) NULL,

    -- fk obrigatoria pra pimenta base (nao deixa apagar pimenta se estiver em receita)
    CONSTRAINT "FK_Molhos_Pimentas_PimentaId"
        FOREIGN KEY ("PimentaId")
        REFERENCES "Pimentas" ("Id")
        ON DELETE RESTRICT,

    -- travas basicas dos valores da receita
    CONSTRAINT "CK_Molhos_Gramas_Positivo" CHECK ("GramasPimentaPorFrasco" > 0),
    CONSTRAINT "CK_Molhos_Embalagem_NaoNegativa" CHECK ("CustoEmbalagemIngredientes" >= 0),
    CONSTRAINT "CK_Molhos_PrecoVenda_Positivo" CHECK ("PrecoVenda" > 0)
);

-- tabela das compras penduradas (dividas) ligadas a cada cliente e opcionalmente ao molho
CREATE TABLE IF NOT EXISTS "Dividas" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ClienteId" INTEGER NOT NULL,
    "MolhoId" INTEGER NULL,
    "QuantidadeFrascos" INTEGER NOT NULL DEFAULT 1,
    "DescricaoMolhos" VARCHAR(300) NOT NULL DEFAULT 'Molhos de pimenta artesanais do Avô Bob',
    "Valor" NUMERIC(10, 2) NOT NULL,
    "SituacaoPaga" BOOLEAN NOT NULL DEFAULT FALSE,
    "DataCriacao" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "DataPagamento" TIMESTAMPTZ NULL,

    -- fk com delete em cascata pra limpar as dividas se remover o cliente
    CONSTRAINT "FK_Dividas_Clientes_ClienteId"
        FOREIGN KEY ("ClienteId")
        REFERENCES "Clientes" ("Id")
        ON DELETE CASCADE,

    -- fk opcional pro molho do catalogo (se excluir o molho, mantem o historico da divida)
    CONSTRAINT "FK_Dividas_Molhos_MolhoId"
        FOREIGN KEY ("MolhoId")
        REFERENCES "Molhos" ("Id")
        ON DELETE SET NULL,

    -- trava pra nao salvar divida com valor ou quantidade zerada/negativa
    CONSTRAINT "CK_Dividas_Valor_Positivo" CHECK ("Valor" > 0),
    CONSTRAINT "CK_Dividas_Quantidade_Positiva" CHECK ("QuantidadeFrascos" > 0)
);

-- indices nas fks pra agilizar consultas
CREATE INDEX IF NOT EXISTS "IX_Molhos_PimentaId"
    ON "Molhos" ("PimentaId");

CREATE INDEX IF NOT EXISTS "IX_Dividas_ClienteId"
    ON "Dividas" ("ClienteId");

CREATE INDEX IF NOT EXISTS "IX_Dividas_MolhoId"
    ON "Dividas" ("MolhoId");
